"use client";
import Header from "@/components/Header"; import Footer from "@/components/Footer"; import {img} from "@/components/siteData";
export default function Contact(){return <><Header/><section className="contact-hero" style={{backgroundImage:`linear-gradient(90deg,rgba(0,30,70,.95),rgba(0,30,70,.45)),url("${img.office}")`}}><div><small>CONTACT US</small><h1>LET'S BUILD A<br/><span>STRONGER TOMORROW</span></h1><p>We are here to assist you. Get in touch with our team for inquiries, product information, technical support, or project requirements.</p></div></section><section className="contact-info-grid"><Box icon="☎" title="Call Us" text="(034) 703 8998" sub="Mon – Fri, 8:00 AM – 5:00 PM"/><Box icon="✉" title="Email Us" text="info@fujipipes.com" sub="We'll get back to you ASAP"/><Box icon="📍" title="Visit Us" text="Brgy. Talisay, Silay City" sub="Negros Occidental, Philippines"/><Box icon="🎧" title="Talk to Our Team" text="Sales & Technical" sub="We're ready to assist you."/></section><section className="contact-layout"><form className="contact-form" onSubmit={e=>e.preventDefault()}><h2>Send Us a Message</h2><p>Fill out the form below and our team will get back to you.</p><div className="form-two"><input placeholder="Full Name *"/><input placeholder="Company Name"/></div><div className="form-two"><input placeholder="Email Address *"/><input placeholder="Contact Number *"/></div><select defaultValue=""><option value="" disabled>Select a subject</option><option>Product Inquiry</option><option>Technical Support</option><option>Sales Inquiry</option><option>Dealer Inquiry</option></select><textarea placeholder="Type your message here..." rows={6}/><button className="blue-button">Send Message →</button></form><div className="map-placeholder"><div className="fake-map"><span>📍</span><strong>FUJIPIPES</strong><p>Brgy. Talisay<br/>Silay City<br/>Negros Occidental</p></div></div><div className="office-box"><h2>Our Head Office</h2><strong>Central Negros Fujipipes Industries, Inc.</strong><p>Brgy. Talisay, Silay City<br/>Negros Occidental, Philippines</p><p>☎ (034) 703 8998</p><p>✉ info@fujipipes.com</p><p>◷ Mon – Fri, 8:00 AM – 5:00 PM</p></div></section><Footer/></>}
function Box({icon,title,text,sub}:{icon:string;title:string;text:string;sub:string}){return <div className="contact-box"><div className="contact-icon">{icon}</div><div><h3>{title}</h3><strong>{text}</strong><p>{sub}</p></div></div>}
